#!/usr/bin/env python3
"""Build third verified batch of 2023 leading-firm-only candidates."""
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]; WORKTABLE=ROOT/"outputs"/"涉农候选公司年份_年报主营业务复核工作表_v7.csv"; OUTPUT=ROOT/"outputs"/"2023龙头企业独有候选_年报复核第三批12家_v1.csv"
R=[
 dict(c="002650",t="1453834677.98",sn="无",s="0",en="粮油食品",e="291600808.42",sc="否",ec="否",bc="否",why="调味品按规则排除；可计粮油初加工收入仅占20.06%，低于30%。"),
 dict(c="002661",t="5184396589.31",sn="生猪养殖",s="359554273.50",en="生猪养殖、外销面粉",e="812284412.67",sc="否",ec="否",bc="否",why="养殖占6.94%，加入面粉初加工后仅15.67%；面条和方便食品未计入。"),
 dict(c="002688",t="2174131033.42",sn="无直接农业收入",s="0",en="兽用化学药品、兽用疫苗、药物饲料添加剂",e="1366180836.72",sc="否",ec="是",bc="否",why="三类农业投入品合计占62.84%，扩展口径达标；淀粉加工未用于扩大分子。"),
 dict(c="002696",t="2720215725.75",sn="无单列直接养殖收入",s="0",en="饲料、水产品加工",e="2495054505.49",sc="否",ec="是",bc="否",why="饲料与水产品初加工合计占91.72%，进入扩展样本。"),
 dict(c="002702",t="1715823986.65",sn="无",s="0",en="速冻鱼肉制品不属于初加工",e="0",sc="否",ec="否",bc="否",why="主营速冻鱼肉制品等食品制造，属于进一步食品加工，按普通食品规则排除。"),
 dict(c="002719",t="708944247.67",sn="未单列奶牛养殖收入",s="0",en="乳制品原奶初加工",e="271929747.28",sc="否",ec="否",bc="是",why="可识别乳制品收入占38.36%，列为边界样本；烘焙和节日食品未计入。"),
 dict(c="002732",t="1950327947.63",sn="未单列奶牛养殖收入",s="0",en="液体乳原奶初加工",e="750454465.96",sc="否",ec="否",bc="是",why="液体乳收入占38.48%，列为边界样本；花式奶和乳酸菌饮料未计入。"),
 dict(c="002746",t="5781232561.22",sn="养殖业",s="130564352.97",en="肉鸡养殖、屠宰食品加工、饲料加工",e="5770748589.13",sc="否",ec="是",bc="否",why="单列养殖收入仅2.26%；养殖、鸡肉初加工和饲料合计占99.82%，扩展口径达标。"),
 dict(c="002847",t="4115175423.46",sn="无",s="0",en="休闲食品不属于扩展范围",e="0",sc="否",ec="否",bc="否",why="主营辣卤、烘焙、深海等休闲零食，按既定规则排除。"),
 dict(c="002852",t="7000856821.01",sn="无单列直接种植收入",s="0",en="食用植物油及粕类加工",e="6974260413.37",sc="否",ec="是",bc="否",why="食品加工板块为食用油和粕类等农产品初加工，占99.62%，进入扩展样本。"),
 dict(c="002873",t="953981876.69",sn="无",s="0",en="医药制造不属于扩展范围",e="0",sc="否",ec="否",bc="否",why="主营中成药等医药制造，未披露达到门槛的直接农业或初加工收入。"),
 dict(c="002910",t="955672655.71",sn="未单列奶牛养殖收入",s="0",en="巴氏杀菌乳、灭菌乳",e="490598217.75",sc="否",ec="是",bc="否",why="巴氏杀菌乳和灭菌乳按原奶初加工合计占51.34%，扩展口径达标；调制乳、发酵乳和含乳饮料未计入。"),
]
def q(v,t): return (Decimal(v)/Decimal(t)).quantize(Decimal("0.00000001"),rounding=ROUND_HALF_UP)
def page(v): return str(int(v)) if isinstance(v,float) and v.is_integer() else str(v)
def main():
 d=pd.read_csv(WORKTABLE,dtype={"股票代码":str}); d=d[(d.年份==2023)&d.股票代码.isin([r["c"] for r in R])].set_index("股票代码"); assert len(d)==12; rows=[]
 for r in R:
  x=d.loc[r["c"]]; sr=q(r["s"],r["t"]); er=q(r["e"],r["t"]); assert (sr>=Decimal("0.5"))==(r["sc"]=="是") and (er>=Decimal("0.5"))==(r["ec"]=="是") and ((Decimal("0.3")<=er<Decimal("0.5"))==(r["bc"]=="是")); eligibility="是（严格样本）" if r["sc"]=="是" else "是（扩展样本）" if r["ec"]=="是" else "否（仅边界稳健性）" if r["bc"]=="是" else "否（低于30%或不属于扩展范围）"
  rows.append({"股票代码":r["c"],"公司全称":x["公司全称"],"年份":2023,"公司营业收入_元":r["t"],"严格口径涉农业务":r["sn"],"严格口径涉农收入_元":r["s"],"严格口径涉农收入占比":f"{sr:.8f}","扩展口径涉农业务":r["en"],"扩展口径涉农收入_元":r["e"],"扩展口径涉农收入占比":f"{er:.8f}","是否存在分部收入重叠":"否（同一披露维度；不符合范围的食品未计入）","严格样本结论":r["sc"],"扩展样本结论":r["ec"],"边界样本结论":r["bc"],"当年曾ST_已核实":"是" if x["当年曾ST_已核实"]=="是" else "否","最终回归样本资格_当前规则":eligibility,"纳入或剔除理由":r["why"],"主营业务证据PDF页序号":page(x["年报主营业务表PDF页序号"]),"营业收入证据PDF页序号":page(x["利润表PDF页序号"]),"年报链接":x["年报链接"],"复核状态":"已人工复核（龙头独有第三批）","复核日期":"2026-08-07"})
 out=pd.DataFrame(rows); assert not out.duplicated(["股票代码","年份"]).any(); out.to_csv(OUTPUT,index=False,encoding="utf-8-sig"); print(out[["股票代码","严格口径涉农收入占比","扩展口径涉农收入占比","严格样本结论","扩展样本结论","边界样本结论","最终回归样本资格_当前规则"]].to_string(index=False))
if __name__=="__main__": main()
